"""Sprinklr API client generated from the Sprinklr Postman collection.

Requires the ``requests`` package.

Calls are nested by API version and then by resource folder. Every call goes
through ``SprinklrClient._request``, which is where logging happens.

    client = SprinklrClient(
        host="https://api2.sprinklr.com",
        api_key="...",
        environment="prod",
        access_token="...",  # optional; set client.access_token later if omitted
    )
    if client.v1.account_ops.activate_account(account_id):
        payload = client.result
    else:
        print(client.error)

``result`` and ``error`` reflect the most recent call. A successful response
(status below 400) returns True and stores the decoded body on ``result``.
An HTTP error or a failed request returns False, clears ``result``, and stores
a ``SprinklrError`` on ``error``. Errors are not raised.

Logging uses the ``sprinklr`` logger. INFO records the method, URL, and status.
DEBUG also records the request body and response body. The API key and access
token are redacted from log messages.

Folder names that are Python keywords are exposed with a trailing underscore,
for example ``client.v1.import_``. Query parameters that are Python keywords
are likewise suffixed (``from_``, ``async_``).
"""

from __future__ import annotations

import json
import logging
from urllib.parse import quote

import requests

logger = logging.getLogger("sprinklr")

__all__ = ["SprinklrClient", "SprinklrError"]


class SprinklrError:
    """Failure from the most recent API call.

    ``status_code`` is None when no HTTP response was received.
    ``body`` is the decoded error response, when one was received.
    """

    def __init__(self, message, status_code=None, body=None):
        self.message = message
        self.status_code = status_code
        self.body = body

    def __str__(self):
        return self.message

    def __repr__(self):
        return (
            "SprinklrError("
            f"status_code={self.status_code!r}, message={self.message!r})"
        )


class SprinklrClient:
    """Client for the Sprinklr API.

    Args:
        host: API host, for example ``https://api2.sprinklr.com``.
        api_key: Value of the ``Key`` header sent on every request.
        environment: Path segment before ``/api``, for example ``prod``.
        access_token: Optional bearer token. Leave it unset to omit the
            ``Authorization`` header until ``access_token`` is assigned.
    """

    def __init__(self, host="https://api3.sprinklr.com", api_key="", environment="prod", access_token=None):
        if not host:
            raise ValueError("host is required")
        if not api_key:
            raise ValueError("api_key is required")
        if not environment:
            raise ValueError("environment is required")
        self.host = str(host).rstrip("/")
        self.api_key = api_key
        self.environment = str(environment).strip("/")
        self.access_token = access_token
        self.timeout = None
        self.result = None
        self.error = None
        self._session = requests.Session()
        self.v1 = _V1(self)
        self.v2 = _V2(self)
        self.v3 = _V3(self)

    def __repr__(self):
        return f"SprinklrClient(host={self.host!r}, environment={self.environment!r})"

    def _redact(self, text):
        if not isinstance(text, str):
            text = str(text)
        if self.api_key:
            text = text.replace(self.api_key, "<api_key>")
        if self.access_token:
            text = text.replace(self.access_token, "<access_token>")
        return text

    def _decode_body(self, response):
        if not response.content:
            return None
        content_type = response.headers.get("Content-Type", "")
        if "json" in content_type.lower():
            try:
                return response.json()
            except ValueError:
                return response.text
        text = response.text
        stripped = text.lstrip()
        if stripped[:1] in "{[":
            try:
                return response.json()
            except ValueError:
                return text
        return text

    def _request(self, method, path, path_params=None, params=None, body=None):
        """Send one API call and record its outcome on this client.

        Returns True when the response status is below 400. Returns False
        when the request fails or the status is 400 or higher.
        """
        self.result = None
        self.error = None
        rendered = path.format(
            **{
                key: quote(str(value), safe="")
                for key, value in (path_params or {}).items()
            }
        )
        url = f"{self.host}/{self.environment}{rendered}"
        query = {
            key: value
            for key, value in (params or {}).items()
            if value is not None
        } or None
        headers = {
            "Key": self.api_key,
            "Content-Type": "application/json",
        }
        if self.access_token:
            headers["Authorization"] = f"Bearer {self.access_token}"

        if body is not None and logger.isEnabledFor(logging.DEBUG):
            try:
                encoded = json.dumps(body)
            except TypeError:
                encoded = str(body)
            logger.debug("request body: %s", self._redact(encoded))

        request_kwargs = {
            "headers": headers,
            "params": query,
            "timeout": self.timeout,
        }
        if body is not None:
            request_kwargs["json"] = body

        try:
            response = self._session.request(method, url, **request_kwargs)
        except (requests.RequestException, TypeError, ValueError) as exc:
            self.error = SprinklrError(message=str(exc))
            logger.info(
                "%s %s -> error: %s",
                method,
                self._redact(url),
                self._redact(str(exc)),
            )
            return False

        logger.info(
            "%s %s -> %s",
            method,
            self._redact(response.url),
            response.status_code,
        )
        if logger.isEnabledFor(logging.DEBUG):
            logger.debug("response body: %s", self._redact(response.text))

        if response.status_code >= 400:
            reason = response.reason or "Request failed"
            self.error = SprinklrError(
                message=f"HTTP {response.status_code} {reason}",
                status_code=response.status_code,
                body=self._decode_body(response),
            )
            return False

        self.result = self._decode_body(response)
        return True


class _V1AccountOps:
    """AccountOps APIs."""

    def __init__(self, client):
        self._client = client

    def activate_account(self, account_id):
        """Activate Account

        PUT /{environment}/api/v1/account/ops/{account_id}/activate

        Args:
            account_id: Path parameter `accountId`
        """
        return self._client._request(
            "PUT",
            "/api/v1/account/ops/{account_id}/activate",
            path_params={"account_id": account_id},
        )

    def deactivate_account(self, account_id):
        """Deactivate Account

        PUT /{environment}/api/v1/account/ops/{account_id}/deactivate

        Args:
            account_id: Path parameter `accountId`
        """
        return self._client._request(
            "PUT",
            "/api/v1/account/ops/{account_id}/deactivate",
            path_params={"account_id": account_id},
        )

    def fetch_account_custom_properties(self):
        """Fetch Account Custom Properties

        GET /{environment}/api/v1/account/ops/additional
        """
        return self._client._request(
            "GET",
            "/api/v1/account/ops/additional",
        )

    def fetch_account_details(
        self,
        account_id,
        *,
        details=None,
    ):
        """Fetch Account Details

        GET /{environment}/api/v1/account/ops/{account_id}/details

        Args:
            account_id: Path parameter `accountId`
            details: Filter or parameter for details
        """
        return self._client._request(
            "GET",
            "/api/v1/account/ops/{account_id}/details",
            path_params={"account_id": account_id},
            params={
                "details": details,
            },
        )

    def update_account_properties(
        self,
        account_id,
        *,
        body=None,
    ):
        """Update Account Properties

        PUT /{environment}/api/v1/account/ops/{account_id}/properties

        Args:
            account_id: Path parameter `accountId`
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "PUT",
            "/api/v1/account/ops/{account_id}/properties",
            path_params={"account_id": account_id},
            body=body,
        )

    def update_cover_image(
        self,
        *,
        body=None,
    ):
        """Update Cover Image

        POST /{environment}/api/v1/account/ops/update/cover-image

        Args:
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "POST",
            "/api/v1/account/ops/update/cover-image",
            body=body,
        )


