class _V3Account:
    """Account APIs."""

    def __init__(self, client):
        self._client = client

    def delete_account(
        self,
        *,
        id=None,
        client_id=None,
    ):
        """Query parameters:
        - id (required): Account id.
        - clientId (required): Client/space id for remove (v2 DELETE /account/{accountId}?clientId=).

        DELETE /{environment}/api/v3/account

        Args:
            id: Account id
            client_id: Client id
        """
        return self._client._request(
            "DELETE",
            "/api/v3/account",
            params={
                "id": id,
                "clientId": client_id,
            },
        )

    def fetch_accounts_by_account_id_or_channel_id_supports_bulk_fetch(
        self,
        *,
        id=None,
        account_type_channel_id=None,
    ):
        """Query Parameters:
        - id: Comma-separated list of Account Id (optional, mutually exclusive with accountTypeChannelId)
        - accountTypeChannelId: Comma-separated list of accountTypeChannelId (optional, mutually exclusive with id)

        Rules:
        1. Only one of id or accountTypeChannelId should be provided, not both
        2. At least one of id or accountTypeChannelId must be provided
        3. Maximum of 50 id/accountTypeChannelId supported for bulk fetch

        GET /{environment}/api/v3/account

        Args:
            id: Comma-separated list of account id
            account_type_channel_id: Comma-separated list of accountTypeChannelId
        """
        return self._client._request(
            "GET",
            "/api/v3/account",
            params={
                "id": id,
                "accountTypeChannelId": account_type_channel_id,
            },
        )

    def partially_update_account_custom_properties_visibility_and_or_active_status(
        self,
        *,
        id=None,
        body=None,
    ):
        """Partially update account (custom properties, visibility, and/or active status)

        PATCH /{environment}/api/v3/account

        Args:
            id: Account id
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "PATCH",
            "/api/v3/account",
            params={
                "id": id,
            },
            body=body,
        )

    def replace_account_custom_properties(
        self,
        *,
        id=None,
        body=None,
    ):
        """Replace account custom properties

        PUT /{environment}/api/v3/account

        Args:
            id: Account id
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "PUT",
            "/api/v3/account",
            params={
                "id": id,
            },
            body=body,
        )


