class _V3Conversation:
    """Conversation APIs."""

    def __init__(self, client):
        self._client = client

    def fetch_conversations_paginated(
        self,
        *,
        channel_type=None,
        channel_id=None,
        message_id=None,
        since_time=None,
        until_time=None,
        page_number=None,
        page_size=None,
        source_type=None,
        sort_key=None,
        sort_order=None,
        parent_sn_msg_id=None,
        msg_types=None,
    ):
        """Returns messages for conversations, paged in the usual v3 format (data, errors, metadata).

        Two modes supported:
        1. Profile conversations: Provide channelType + channelId to fetch conversations for a social profile
        2. Message conversations: Provide messageId to fetch conversations for a specific message thread

        You must provide either (channelType + channelId) OR messageId, but not both.

        Pagination: the first page is page 0, then 1, 2, and so on. pageSize is how many rows to return (default 20, up to
        100). The response does not include a total number of messages; use metadata.hasMore to see if another page
        exists. If hasMore is true, request the next pageNumber.

        Profile Conversation Request parameters:
        - channelType (required for this mode) — social network, e.g. FACEBOOK, TWITTER.
        - channelId (required for profile mode) — id of the social account.
        - sinceTime — optional & inclusive; only messages at or after this time, in milliseconds epoch.
        - untilTime — optional & inclusive; only messages at or before this time, in milliseconds epoch.
        - pageNumber — optional; default 0. Page index (0 = first page).
        - pageSize — optional; default 20, maximum 100.
        - sourceType — optional; narrows results by message source.
        - sortKey — required; a Message field name for sorting.
        - sortOrder — optional; ASC or DESC (default), required when sortKey is set.

        Message Conversation Request parameters:
        - messageId (required for this mode) — Universal message ID to fetch conversation thread for.
        - parentSnMsgId — optional; filter by parent message ID within the conversation.
        - msgTypes — optional; comma-separated list of message type integers to filter on.
        - pageNumber — optional; default 0. Page index (0 = first page). Same as profile mode.
        - pageSize — optional; default 20, maximum 100. Same as profile mode.
        - sinceTime — optional & inclusive; only messages at or after this time, in milliseconds epoch.
        - untilTime — optional & inclusive; only messages at or before this time, in milliseconds epoch.
        - sortKey — optional; a Message field name for sorting.
        - sortOrder — optional; ASC or DESC (default), required when sortKey is set.

        GET /{environment}/api/v3/conversation

        Args:
            channel_type: Channel type (required for profile conversations)
            channel_id: Channel id (required for profile conversations)
            message_id: Message ID (required for message conversations)
            since_time: Since time lower bound (epoch ms)
            until_time: Until time upper bound (epoch ms)
            page_number: 0-based page index; offset is pageNumber * pageSize
            page_size: Page size / rows
            source_type: SourceType enum name
            sort_key: Message field name, case-sensitive; (associatedCaseNumber, channelCreatedTime, channelMessageId, createdTime, modifiedTime, or parentMessageId). Omit for default (createdTime ASC).
            sort_order: Sort order (ASC/DESC)
            parent_sn_msg_id: Parent message ID for message conversation filtering
            msg_types: Comma-separated message type integers for filtering
        """
        return self._client._request(
            "GET",
            "/api/v3/conversation",
            params={
                "channelType": channel_type,
                "channelId": channel_id,
                "messageId": message_id,
                "sinceTime": since_time,
                "untilTime": until_time,
                "pageNumber": page_number,
                "pageSize": page_size,
                "sourceType": source_type,
                "sortKey": sort_key,
                "sortOrder": sort_order,
                "parentSnMsgId": parent_sn_msg_id,
                "msgTypes": msg_types,
            },
        )


