class _V3StandardEntityRecord:
    """Standard Entity Record APIs."""

    def __init__(self, client):
        self._client = client

    def create_a_new_standard_entity_record(
        self,
        *,
        body=None,
    ):
        """Create a new standard entity record.

        POST /{environment}/api/v3/standardEntity/record

        Args:
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "POST",
            "/api/v3/standardEntity/record",
            body=body,
        )

    def delete_standard_entity_records_by_entity_id_or_record_id(
        self,
        *,
        entity_id=None,
        record_id=None,
        entity_type=None,
    ):
        """Delete standard entity records by entityId or recordId.

        DELETE /{environment}/api/v3/standardEntity/record

        Args:
            entity_id: Comma-separated list of entity IDs
            record_id: Comma-separated list of record IDs
            entity_type: Entity type (required)
        """
        return self._client._request(
            "DELETE",
            "/api/v3/standardEntity/record",
            params={
                "entityId": entity_id,
                "recordId": record_id,
                "entityType": entity_type,
            },
        )

    def fetch_standard_entity_records_by_entity_id_record_id_primary_key_or_primary_key_prefix(
        self,
        *,
        entity_id=None,
        record_id=None,
        entity_type=None,
        primary_key=None,
        primary_key_prefix=None,
        page_number=None,
        page_size=None,
    ):
        """All modes require 'entityType' parameter.
        Mode 1 - Fetch by entityId:
        - entityId: Comma-separated list of entity IDs (max 50)
        Mode 2 - Fetch by recordId:
        - recordId: Comma-separated list of record IDs (max 50)
        Mode 3 - Fetch by primary key:
        - primaryKey: true (required) + primary key field query params
        Mode 4 - Fetch by primary key prefix:
        - primaryKeyPrefix: true (required) + primary key prefix field query params

        GET /{environment}/api/v3/standardEntity/record

        Args:
            entity_id: Comma-separated list of entity IDs
            record_id: Comma-separated list of record IDs
            entity_type: Entity type (required)
            primary_key: Primary key exact lookup flag
            primary_key_prefix: Primary key prefix lookup flag
            page_number: Page number for pagination
            page_size: Page size for pagination
        """
        return self._client._request(
            "GET",
            "/api/v3/standardEntity/record",
            params={
                "entityId": entity_id,
                "recordId": record_id,
                "entityType": entity_type,
                "primaryKey": primary_key,
                "primaryKeyPrefix": primary_key_prefix,
                "pageNumber": page_number,
                "pageSize": page_size,
            },
        )

    def patch_update_a_standard_entity_record(
        self,
        *,
        entity_id=None,
        record_id=None,
        entity_type=None,
        body=None,
    ):
        """Performs a partial update using a list of UpdateField operations.
        Supports both entityId and recordId parameters with entityType.

        PATCH /{environment}/api/v3/standardEntity/record

        Args:
            entity_id: Entity ID
            record_id: Record ID
            entity_type: Entity type (required)
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "PATCH",
            "/api/v3/standardEntity/record",
            params={
                "entityId": entity_id,
                "recordId": record_id,
                "entityType": entity_type,
            },
            body=body,
        )

    def update_a_standard_entity_record(
        self,
        *,
        entity_id=None,
        record_id=None,
        entity_type=None,
        body=None,
    ):
        """Consolidates V2 updateEntity and updateEntityByEntityId endpoints.
        Supports update by entityId or recordId with entityType.
        Validates that entity type matches between path parameter and request body.
        For entityId updates: validates entityId matches between path parameter and request body.

        PUT /{environment}/api/v3/standardEntity/record

        Args:
            entity_id: Entity ID
            record_id: Record ID
            entity_type: Entity type (required)
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "PUT",
            "/api/v3/standardEntity/record",
            params={
                "entityId": entity_id,
                "recordId": record_id,
                "entityType": entity_type,
            },
            body=body,
        )

    def upsert_standard_entity_record(
        self,
        *,
        body=None,
    ):
        """Creates a new record if it doesn't exist, otherwise updates the existing record.
        Automatically determines upsert method based on request body:
        - If entityId is present in body: uses upsert by entityId
        - If entityId is not present in body: uses upsert by primary key
        Consolidates functionality from v2 API upsertEntity and upsertEntityByPrimaryKey endpoints.

        POST /{environment}/api/v3/standardEntity/record/upsert

        Args:
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "POST",
            "/api/v3/standardEntity/record/upsert",
            body=body,
        )


