class _V3UserAssignmentConfig:
    """User Assignment Config APIs."""

    def __init__(self, client):
        self._client = client

    def create_or_replace_user_assignment_configuration(
        self,
        *,
        body=None,
    ):
        """Body must include userId. Replaces capacities and proficiencies with the payload (omitted proficiency maps are cleared).

        Not supported when assignment settings are enabled for the partner.

        Returns 201 Created with the saved configuration in data.

        POST /{environment}/api/v3/userAssignmentConfig

        Args:
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "POST",
            "/api/v3/userAssignmentConfig",
            body=body,
        )

    def fetch_user_assignment_configuration(
        self,
        *,
        user_id=None,
    ):
        """Query parameter (required):
        - userId: User id

        Response is 200 with data containing a one-element list when found; 404 when no config exists for the user.

        GET /{environment}/api/v3/userAssignmentConfig

        Args:
            user_id: User id
        """
        return self._client._request(
            "GET",
            "/api/v3/userAssignmentConfig",
            params={
                "userId": user_id,
            },
        )

    def partial_update_user_assignment_configuration(
        self,
        *,
        user_id=None,
        body=None,
    ):
        """Query parameter (required):
        - userId: User id

        Body: UserAssignmentConfigUpdateRequest. Omitted fields are unchanged.

        Provide at least one of:
        - capacities: add or update capacity entries
        - capacitiesToRemove: capacity ids to delete
        - proficiencies.skillVsProficiency: skill id to proficiency score (1-100)
        - proficiencies.languageVsProficiency: language to proficiency score
        - proficiencies.channelVsProficiency: channel to proficiency score
        - skillsToRemove: skill ids to remove (each entry must be a non-blank skill id)
        - languagesToRemove: language ids to remove (each entry must be a non-blank id)
        - channelsToRemove: channel ids to remove (each entry must be a non-blank id)
        - capacityConfigId
        - timeZone

        An empty proficiencies object without maps is not accepted as an update.

        Not supported when assignment settings are enabled for the partner.

        Returns 204 No Content on success.

        PATCH /{environment}/api/v3/userAssignmentConfig

        Args:
            user_id: User id
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "PATCH",
            "/api/v3/userAssignmentConfig",
            params={
                "userId": user_id,
            },
            body=body,
        )

    def replace_user_assignment_configuration(
        self,
        *,
        user_id=None,
        body=None,
    ):
        """Query parameter (required):
        - userId: User id

        Body: full UserAssignmentConfig (same replace semantics as POST). Capacities and proficiencies in the payload
        replace existing values; omitted proficiency maps are cleared.

        Not supported when assignment settings are enabled for the partner.

        Returns 204 No Content on success.

        PUT /{environment}/api/v3/userAssignmentConfig

        Args:
            user_id: User id
            body: JSON object sent as the request body.
        """
        return self._client._request(
            "PUT",
            "/api/v3/userAssignmentConfig",
            params={
                "userId": user_id,
            },
            body=body,
        )


